import os, json, collections, statistics

data_dir = '/root/autodl-tmp/structfuse/m1_extraction/'
files = [f for f in os.listdir(data_dir) if f.endswith('.json')]

repo_data = collections.defaultdict(lambda: {
    'total': 0, 'has_extra_connected': 0, 'times': [],
    'timeout': 0, 'error': 0, 'success': 0,
    'cg_nonempty': 0, 'df_nonempty': 0
})

for i, fn in enumerate(files):
    fpath = os.path.join(data_dir, fn)
    try:
        with open(fpath) as f:
            inst = json.load(f)
    except:
        continue

    repo = fn.split('.')[0]
    rd = repo_data[repo]
    rd['total'] += 1
    t = inst.get('extraction_time_s')
    if t is not None:
        rd['times'].append(t)
    err = inst.get('error')
    if err:
        rd['error'] += 1
        if 'timeout' in str(err).lower():
            rd['timeout'] += 1
    else:
        rd['success'] += 1
    cg = inst.get('call_graph', [])
    df = inst.get('dataflow_paths', [])
    if cg:
        rd['cg_nonempty'] += 1
    if df:
        rd['df_nonempty'] += 1
    gold = set(inst.get('gold_patch_files', []))
    connected = set()
    for item in cg:
        if isinstance(item, dict):
            for key in ['caller_file', 'callee_file', 'file_path', 'source_file', 'target_file']:
                if key in item:
                    connected.add(item[key])
    for item in df:
        if isinstance(item, dict):
            for key in ['source_file', 'sink_file', 'file_path']:
                if key in item:
                    connected.add(item[key])
    if connected - gold:
        rd['has_extra_connected'] += 1

# Output as JSON for easy consumption
import json as j
result = {
    'repos': {},
    'aggregate': {},
    'z_by_size': {}
}

all_times = []
total_all = total_success = total_error = total_timeout = total_z = 0
small = []
medium = []
large = []

for repo in sorted(repo_data.keys(), key=lambda r: -repo_data[r]['total']):
    rd = repo_data[repo]
    n = rd['total']
    total_all += n
    total_success += rd['success']
    total_error += rd['error']
    total_timeout += rd['timeout']
    total_z += rd['has_extra_connected']
    all_times.extend(rd['times'])
    avg_t = statistics.mean(rd['times']) if rd['times'] else 0
    z_pct = rd['has_extra_connected'] / n * 100 if n else 0
    cg_pct = rd['cg_nonempty'] / n * 100 if n else 0
    df_pct = rd['df_nonempty'] / n * 100 if n else 0
    result['repos'][repo] = {
        'n': n, 'success': rd['success'], 'error': rd['error'],
        'timeout': rd['timeout'], 'cg_pct': round(cg_pct, 1),
        'df_pct': round(df_pct, 1), 'z_pct': round(z_pct, 1),
        'avg_extraction_time_s': round(avg_t, 2)
    }
    bucket = {'repo': repo, 'n': n, 'z_pct': z_pct}
    if n < 100:
        small.append(bucket)
    elif n <= 500:
        medium.append(bucket)
    else:
        large.append(bucket)

def bz(repos):
    tn = sum(r['n'] for r in repos)
    tz = sum(r['n'] * r['z_pct'] / 100 for r in repos)
    return round(tz / tn * 100, 1) if tn else 0

sorted_times = sorted(all_times)
result['aggregate'] = {
    'total_instances': total_all,
    'total_repos': len(repo_data),
    'success': total_success,
    'success_pct': round(total_success / total_all * 100, 1),
    'error': total_error,
    'error_pct': round(total_error / total_all * 100, 1),
    'timeout': total_timeout,
    'timeout_pct': round(total_timeout / total_all * 100, 1),
    'z_total': total_z,
    'z_pct': round(total_z / total_all * 100, 1),
    'skip_clone_failed': 660,
    'extraction_time': {
        'mean': round(statistics.mean(all_times), 2) if all_times else 0,
        'median': round(statistics.median(all_times), 2) if all_times else 0,
        'p95': round(sorted_times[int(len(sorted_times) * 0.95)], 2) if all_times else 0,
        'max': round(max(all_times), 2) if all_times else 0,
        'min': round(min(all_times), 2) if all_times else 0,
    }
}
result['z_by_size'] = {
    'small_lt100': {'repos': len(small), 'instances': sum(r['n'] for r in small), 'z_pct': bz(small)},
    'medium_100_500': {'repos': len(medium), 'instances': sum(r['n'] for r in medium), 'z_pct': bz(medium)},
    'large_gt500': {'repos': len(large), 'instances': sum(r['n'] for r in large), 'z_pct': bz(large)},
}

with open('/tmp/scalability_stats.json', 'w') as out:
    j.dump(result, out, indent=2)
print('DONE')
PYEOF
